// ---------------------------------------------------------------------------
// DealerService
// ---------------------------------------------------------------------------
DealerService::DealerService(DealerConfig cfg, TcpListener&& listener)
    : cfg_(std::move(cfg)), listener_(std::move(listener)) {
  // rng_ is default constructed from the OS CSPRNG (lowlevel::Rng::from_os_or_abort:
  // BCryptGenRandom / /dev/urandom). Only the explicit insecure test mode
  // replaces it by a seeded stream; any other mode string keeps OS randomness
  // and its bundles are still marked insecure (mode != ISOLATED_RECIPIENT_BUNDLES).
  if (cfg_.mode == "INSECURE_TEST_ONLY_SHARED_SEED") rng_ = detail::ChaCha20::from_seed(cfg_.test_seed);
  refill_last_ = monotonic_s();
  register_builtin_generators();
}

DealerService::~DealerService() { stop(); }

void DealerService::register_generator(const std::string& material_type, MaterialGenerator gen) {
  std::lock_guard<std::mutex> lk(mu_);
  generators_[material_type] = std::move(gen);
}

void DealerService::register_builtin_generators() {
  std::lock_guard<std::mutex> lk(mu_);
  generators_["beaver"] = gen_beaver;
  generators_["kary_select"] = gen_beaver;
  generators_["matrix_triple"] = gen_matrix_triple;
  generators_["vector_share"] = gen_vector_share;
  generators_["wmask_mask"] = gen_wmask_mask;
  generators_["wmask_call"] = gen_wmask_call;
#ifdef OPENCRAB2_PLATFORM_HAVE_LOWLEVEL_MATERIAL
  generators_["drelu"] = gen_drelu;
  generators_["trunc_faithful"] = gen_trunc;
  generators_["ring_to_field"] = gen_r2f;
#endif
}

bool DealerService::lowlevel_material_available() {
#ifdef OPENCRAB2_PLATFORM_HAVE_LOWLEVEL_MATERIAL
  return true;
#else
  return false;
#endif
}

bool DealerService::supports(const std::string& material_type) const {
  std::lock_guard<std::mutex> lk(mu_);
  return generators_.count(material_type) != 0;
}

std::vector<std::string> DealerService::supported_types() const {
  std::lock_guard<std::mutex> lk(mu_);
  std::vector<std::string> out;
  for (const auto& kv : generators_) out.push_back(kv.first);
  return out;
}

DealerService::Stats DealerService::stats() const {
  std::lock_guard<std::mutex> lk(mu_);
  Stats s = stats_;
  s.pending_halves = pending_total();
  return s;
}

size_t DealerService::pending_total() const {
  size_t pending = 0;
  for (const auto& kv : pending_) pending += kv.second.size();
  for (const auto& kv : named_) pending += 2 * kv.second.pairs.size() - kv.second.next[0] - kv.second.next[1];
  return pending;
}

std::string DealerService::pending_key(const MaterialRequest& req) const {
  return material_type_string(req.material_type, req.params) + "|" + std::to_string(req.count) + "|" + req.gate_id;
}

Expected<bool> DealerService::wait_refill(size_t nbytes) {
  if (cfg_.refill_bytes_per_s == 0) return make_ok(true);
  // token bucket on provisioned bytes (the declared material refill rate)
  double now = monotonic_s();
  refill_tokens_ += (now - refill_last_) * static_cast<double>(cfg_.refill_bytes_per_s);
  refill_last_ = now;
  double cap = static_cast<double>(cfg_.refill_bytes_per_s) * cfg_.max_refill_wait_s;
  if (refill_tokens_ > cap) refill_tokens_ = cap;
  double deficit = static_cast<double>(nbytes) - refill_tokens_;
  if (deficit <= 0) {
    refill_tokens_ -= static_cast<double>(nbytes);
    return make_ok(true);
  }
  double wait = deficit / static_cast<double>(cfg_.refill_bytes_per_s);
  if (wait > cfg_.max_refill_wait_s) return make_fail<bool>("MATERIAL_STALL");
  sleep_s(wait);
  refill_tokens_ = 0;
  refill_last_ = monotonic_s();
  return make_ok(true);
}

wire::Value DealerService::make_header(int recipient, const MaterialRequest& req, const std::string& material_id,
                                       int64_t count, size_t nbytes, const std::vector<std::string>& parts,
                                       const wire::Value& header_params) const {
  wire::Value h = wire::Value::make_dict();
  h.set("profile_id", wire::Value::from_str(cfg_.profile_id));
  h.set("setup_id", wire::Value::from_str(cfg_.setup_id));
  h.set("model_version", wire::Value::from_str(cfg_.model_version));
  h.set("numeric_contract_hash", wire::Value::from_str(cfg_.numeric_contract_hash));
  h.set("recipient", wire::Value::from_int(recipient));
  h.set("gate_id", wire::Value::from_str(req.gate_id));
  h.set("material_type", wire::Value::from_str(req.material_type));
  h.set("material_id", wire::Value::from_str(material_id));
  h.set("count", wire::Value::from_int(count));
  h.set("bytes", wire::Value::from_int(static_cast<int64_t>(nbytes)));
  // The recipient's own request keys (sizes only for payload-like values),
  // completed with the public shape keys of the generator in both spellings.
  wire::Value params = public_params(req.params);
  if (header_params.is_dict()) {
    for (const auto& kv : header_params.dict) params.set(kv.first, kv.second);
  }
  if (req.material_type == "wmask_mask") params.set("model_version", wire::Value::from_str(cfg_.model_version));
  h.set("params", std::move(params));
  std::vector<wire::Value> pl;
  for (const auto& p : parts) pl.push_back(wire::Value::from_str(p));
  h.set("parts", wire::Value::from_list(std::move(pl)));
  h.set("dealer_mode", wire::Value::from_str(cfg_.mode));
  h.set("insecure", wire::Value::from_bool(cfg_.mode != "ISOLATED_RECIPIENT_BUNDLES"));
  return h;
}

Expected<Bundle> DealerService::produce(const MaterialRequest& req) {
  if (req.recipient != 0 && req.recipient != 1) return make_fail<Bundle>("DEALER_UNKNOWN_RECIPIENT");
  if (cfg_.recipient_keys.find(req.recipient) == cfg_.recipient_keys.end()) return make_fail<Bundle>("DEALER_UNKNOWN_RECIPIENT");
  if (req.count <= 0) return make_fail<Bundle>("MATERIAL_BAD_PARAMS");
  std::lock_guard<std::mutex> lk(mu_);
  // Halves wait under "<type|params|count|gate>|for<recipient>": the recipient
  // that requests second pops the half its peer's identical REQ left behind.
  std::string base_key = pending_key(req);
  std::string my_key = base_key + "|for" + std::to_string(req.recipient);
  std::string peer_key = base_key + "|for" + std::to_string(1 - req.recipient);
  PendingHalf mine;
  auto pit = pending_.find(my_key);
  if (pit != pending_.end() && !pit->second.empty()) {
    mine = std::move(pit->second.front());
    pit->second.pop_front();
    if (pit->second.empty()) pending_.erase(pit);
  } else {
    if (pending_total() >= cfg_.max_pending_halves) {
      stats_.requests_rejected++;
      return make_fail<Bundle>("DEALER_PENDING_OVERFLOW");
    }
    auto halves = generate_halves(req);
    if (!halves.ok) return forward_fail<Bundle>(halves);
    mine = std::move(req.recipient == 0 ? halves.value.first : halves.value.second);
    pending_[peer_key].push_back(std::move(req.recipient == 0 ? halves.value.second : halves.value.first));
  }
  auto b = seal_half(req, mine);
  if (!b.ok && b.code == "MATERIAL_STALL") {
    // put it back so that nothing is lost; the recipient retries later
    pending_[my_key].push_front(std::move(mine));
  }
  return b;
}

Expected<std::pair<DealerService::PendingHalf, DealerService::PendingHalf>> DealerService::generate_halves(
    const MaterialRequest& req) {
  using R = std::pair<PendingHalf, PendingHalf>;
  auto git = generators_.find(req.material_type);
  if (git == generators_.end()) {
    stats_.requests_rejected++;
    return make_fail<R>("MATERIAL_TYPE_UNSUPPORTED");
  }
  // The isolated dealer never accepts a plaintext vector (it would learn a model value). The
  // weight-blind form {name, size} (a zero sharing that P0 completes locally) stays available;
  // the {name, values} form is served by the insecure test mode only.
  if (req.material_type == "vector_share" && cfg_.mode == "ISOLATED_RECIPIENT_BUNDLES" && req.params.get("values")) {
    stats_.requests_rejected++;
    return make_fail<R>("DEALER_PLAINTEXT_REFUSED");
  }
  auto pair = git->second(req, rng_, state_);
  if (!pair.ok) {
    stats_.requests_rejected++;
    return forward_fail<R>(pair);
  }
  if (pair.value.payload0.size() > cfg_.max_payload_bytes || pair.value.payload1.size() > cfg_.max_payload_bytes) {
    stats_.requests_rejected++;
    return make_fail<R>("MATERIAL_TOO_LARGE");
  }
  uint8_t nonce[8];
  rng_.fill(nonce, 8);
  char idbuf[32];
  std::snprintf(idbuf, sizeof idbuf, "%08llu", static_cast<unsigned long long>(material_counter_++));
  std::string material_id = req.material_type + "-" + cfg_.setup_id + "-" + detail::hex_encode(nonce, 8) + "-" + idbuf;
  R out;
  out.first.material_id = material_id;
  out.first.parts = pair.value.parts;
  out.first.count = pair.value.count;
  out.first.header_params = pair.value.header_params;
  out.second = out.first;
  out.first.payload = std::move(pair.value.payload0);
  out.second.payload = std::move(pair.value.payload1);
  stats_.pairs_generated++;
  return make_ok(std::move(out));
}

Expected<Bundle> DealerService::seal_half(const MaterialRequest& req, PendingHalf& half) {
  auto kit = cfg_.recipient_keys.find(req.recipient);
  if (kit == cfg_.recipient_keys.end()) return make_fail<Bundle>("DEALER_UNKNOWN_RECIPIENT");
  auto rf = wait_refill(half.payload.size());
  if (!rf.ok) {
    stats_.requests_rejected++;
    return forward_fail<Bundle>(rf);   // MATERIAL_STALL: the caller keeps the half
  }
  Bundle b;
  b.header = make_header(req.recipient, req, half.material_id, half.count, half.payload.size(), half.parts, half.header_params);
  b.payload = std::move(half.payload);
  b.tag = header_tag(kit->second, b.header, b.payload);
  if (b.tag.empty()) {
    // fail closed: an untaggable header is never sent (the half is burned, not requeued)
    stats_.requests_rejected++;
    return make_fail<Bundle>("DEALER_HEADER_NOT_CANONICAL");
  }
  stats_.bundles_sent++;
  stats_.bytes_sent += b.payload.size();
  return make_ok(std::move(b));
}

// Named request: `count` bundles of one item each (the Python client's reading of REQ).
// A request without a per-item size (Beaver-like material without `shape`, DCF-based material
// without `M`) keeps the C++ spelling: one bundle of `count` elements.
Expected<Bundle> DealerService::produce_named(const MaterialRequest& req, const std::string& request_id, int64_t& remaining) {
  remaining = 0;
  if (req.recipient != 0 && req.recipient != 1) return make_fail<Bundle>("DEALER_UNKNOWN_RECIPIENT");
  if (cfg_.recipient_keys.find(req.recipient) == cfg_.recipient_keys.end()) return make_fail<Bundle>("DEALER_UNKNOWN_RECIPIENT");
  if (req.count <= 0 || request_id.empty() || request_id.size() > 512) return make_fail<Bundle>("MATERIAL_BAD_PARAMS");
  std::lock_guard<std::mutex> lk(mu_);
  const std::string fingerprint = pending_key(req);
  auto it = named_.find(request_id);
  if (it == named_.end()) {
    const std::string& t = req.material_type;
    const bool beaver_like = t == "beaver" || t == "kary_select";
    const bool dcf_like = t == "drelu" || t == "trunc_faithful" || t == "ring_to_field";
    const bool per_item = (beaver_like && req.params.get("shape") != nullptr) || (dcf_like && pos_int(req.params, "M") > 0) ||
                          t == "matrix_triple" || t == "wmask_call";
    if (!per_item && !beaver_like && !dcf_like && req.count != 1) {
      stats_.requests_rejected++;
      return make_fail<Bundle>("MATERIAL_BAD_PARAMS");   // wmask_mask, vector_share: exactly one bundle
    }
    const int64_t bundles = per_item ? req.count : 1;
    if (bundles > 4096 || pending_total() + 2 * static_cast<size_t>(bundles) > cfg_.max_pending_halves) {
      stats_.requests_rejected++;
      return make_fail<Bundle>("DEALER_PENDING_OVERFLOW");
    }
    MaterialRequest one = req;
    if (per_item) one.count = 1;
    NamedRequest nr;
    nr.fingerprint = fingerprint;
    for (int64_t i = 0; i < bundles; ++i) {
      auto halves = generate_halves(one);
      if (!halves.ok) return forward_fail<Bundle>(halves);   // nothing of this request is kept
      nr.pairs.push_back(std::move(halves.value));
    }
    it = named_.emplace(request_id, std::move(nr)).first;
  } else if (it->second.fingerprint != fingerprint) {
    stats_.requests_rejected++;
    return make_fail<Bundle>("DEALER_REQUEST_CONFLICT");
  }
  NamedRequest& nr = it->second;
  const int r = req.recipient;
  if (nr.next[r] >= nr.pairs.size()) {
    stats_.requests_rejected++;
    return make_fail<Bundle>("DEALER_ALREADY_DELIVERED");
  }
  PendingHalf& half = r == 0 ? nr.pairs[nr.next[r]].first : nr.pairs[nr.next[r]].second;
  auto b = seal_half(req, half);
  if (!b.ok && b.code == "MATERIAL_STALL") return b;   // the half stays in place; the recipient retries later
  nr.next[r]++;                                        // delivered, or burned by a fail-closed seal
  remaining = static_cast<int64_t>(nr.pairs.size() - nr.next[r]);
  if (nr.next[0] >= nr.pairs.size() && nr.next[1] >= nr.pairs.size()) named_.erase(it);
  return b;
}

Expected<bool> DealerService::start() {
  if (!listener_.valid()) return make_fail<bool>("TCP_INVALID_SOCKET");
  if (started_.exchange(true)) return make_ok(true);
  stopping_ = false;
  accept_thread_ = std::thread([this]() { accept_loop(); });
  return make_ok(true);
}

void DealerService::stop() {
  if (!started_) return;
  stopping_ = true;
  listener_.close();
  {
    std::lock_guard<std::mutex> lk(mu_);
    for (auto& w : live_) {
      if (auto s = w.lock()) s->shutdown_both();
    }
  }
  if (accept_thread_.joinable()) accept_thread_.join();
  std::vector<std::thread> workers;
  {
    std::lock_guard<std::mutex> lk(mu_);
    workers.swap(workers_);
    live_.clear();
  }
  for (auto& t : workers) {
    if (t.joinable()) t.join();
  }
  started_ = false;
}

void DealerService::accept_loop() {
  while (!stopping_) {
    auto c = listener_.accept(0.2);
    if (!c.ok) {
      if (c.code == "TCP_TIMEOUT") continue;
      if (stopping_) break;
      sleep_s(0.01);
      continue;
    }
    auto sock = std::make_shared<TcpSocket>(std::move(c.value));
    std::lock_guard<std::mutex> lk(mu_);
    stats_.connections++;
    size_t keep = 0;
    for (size_t i = 0; i < live_.size(); ++i) {
      if (!live_[i].expired()) {
        live_[keep] = live_[i];
        if (keep != i) workers_[keep] = std::move(workers_[i]);
        ++keep;
      } else if (workers_[i].joinable()) {
        workers_[i].join();
      }
    }
    live_.resize(keep);
    workers_.resize(keep);
    live_.push_back(sock);
    workers_.emplace_back([this, sock]() { serve(sock); });
  }
}

Expected<bool> DealerService::send_msg(TcpSocket& sock, const wire::Value& v) {
  std::vector<uint8_t> payload = wire::encode(v);
  return sock.send_frame(payload);
}

Expected<wire::Value> DealerService::recv_msg(TcpSocket& sock) {
  auto f = sock.recv_frame(static_cast<size_t>(1) << 24);
  if (!f.ok) return forward_fail<wire::Value>(f);
  return wire::decode(f.value);
}

void DealerService::send_error(TcpSocket& sock, const std::string& code) {
  wire::Value e = wire::Value::make_dict();
  e.set("type", wire::Value::from_str("ERROR"));
  e.set("code", wire::Value::from_str(code));
  send_msg(sock, e);
}

void DealerService::serve(std::shared_ptr<TcpSocket> sock) {
  sock->set_timeout(cfg_.io_timeout_s);
  // HELLO
  auto hello = recv_msg(*sock);
  if (!hello.ok || hello.value.str_or("type", "") != "HELLO") {
    send_error(*sock, "DEALER_BAD_MESSAGE");
    return;
  }
  int recipient = static_cast<int>(hello.value.int_or("recipient", -1));
  std::string setup_id = hello.value.str_or("setup_id", "");
  std::string contract = hello.value.str_or("contract_hash", "");
  auto kit = cfg_.recipient_keys.find(recipient);
  if ((recipient != 0 && recipient != 1) || kit == cfg_.recipient_keys.end()) {
    std::lock_guard<std::mutex> lk(mu_);
    stats_.auth_failures++;
    send_error(*sock, "DEALER_UNKNOWN_RECIPIENT");
    return;
  }
  if (setup_id != cfg_.setup_id) {
    send_error(*sock, "SETUP_MISMATCH");
    return;
  }
  if (contract != cfg_.numeric_contract_hash) {
    send_error(*sock, "CONTRACT_MISMATCH");
    return;
  }
  // CHALLENGE
  std::vector<uint8_t> nonce = detail::os_random_bytes(32);
  wire::Value ch = wire::Value::make_dict();
  ch.set("type", wire::Value::from_str("CHALLENGE"));
  ch.set("nonce", wire::Value::from_bytes(nonce));
  ch.set("dealer_mode", wire::Value::from_str(cfg_.mode));
  ch.set("model_version", wire::Value::from_str(cfg_.model_version));
  ch.set("profile_id", wire::Value::from_str(cfg_.profile_id));
  if (!send_msg(*sock, ch).ok) return;
  // AUTH
  auto auth = recv_msg(*sock);
  if (!auth.ok || auth.value.str_or("type", "") != "AUTH") {
    send_error(*sock, "DEALER_BAD_MESSAGE");
    return;
  }
  std::string expected = auth_tag(kit->second, nonce);
  std::string presented = auth.value.str_or("tag", "");
  if (!detail::constant_time_equal(presented, expected)) {
    {
      std::lock_guard<std::mutex> lk(mu_);
      stats_.auth_failures++;
    }
    send_error(*sock, "AUTH_FAILED");
    return;
  }
  wire::Value ok = wire::Value::make_dict();
  ok.set("type", wire::Value::from_str("AUTH_OK"));
  ok.set("recipient", wire::Value::from_int(recipient));
  if (!send_msg(*sock, ok).ok) return;
  // REQ loop
  while (!stopping_) {
    auto m = recv_msg(*sock);
    if (!m.ok) return;  // peer closed or timeout: end of session
    std::string type = m.value.str_or("type", "");
    if (type == "BYE") return;
    if (type == "STATUS") {
      Stats s = stats();
      wire::Value st = wire::Value::make_dict();
      st.set("type", wire::Value::from_str("STATUS"));
      st.set("bundles_sent", wire::Value::from_int(static_cast<int64_t>(s.bundles_sent)));
      st.set("bytes_sent", wire::Value::from_int(static_cast<int64_t>(s.bytes_sent)));
      st.set("pending_halves", wire::Value::from_int(static_cast<int64_t>(s.pending_halves)));
      st.set("dealer_mode", wire::Value::from_str(cfg_.mode));
      if (!send_msg(*sock, st).ok) return;
      continue;
    }
    if (type != "REQ") {
      send_error(*sock, "DEALER_BAD_MESSAGE");
      return;
    }
    MaterialRequest req;
    req.material_type = m.value.str_or("material_type", "");
    const wire::Value* params = m.value.get("params");
    req.params = (params && params->is_dict()) ? *params : wire::Value::make_dict();
    req.count = m.value.int_or("count", 0);
    req.gate_id = m.value.str_or("gate_id", "");
    req.recipient = recipient;
    // request_id present: the named form (count bundles of one item each, `remaining` counts down)
    const wire::Value* rid = m.value.get("request_id");
    if (rid && !rid->is_str()) {
      send_error(*sock, "MATERIAL_BAD_PARAMS");
      continue;
    }
    int64_t remaining = 0;
    auto b = rid ? produce_named(req, rid->s, remaining) : produce(req);
    if (!b.ok) {
      send_error(*sock, b.code);
      // keep the session open for recoverable errors only
      if (b.code == "MATERIAL_STALL" || b.code == "MATERIAL_TYPE_UNSUPPORTED" || b.code == "MATERIAL_BAD_PARAMS" ||
          b.code == "WMASK_NOT_INSTALLED" || b.code == "MATERIAL_TOO_LARGE" || b.code == "DEALER_REQUEST_CONFLICT" ||
          b.code == "DEALER_ALREADY_DELIVERED" || b.code == "DEALER_PLAINTEXT_REFUSED")
        continue;
      return;
    }
    wire::Value bundle = wire::Value::make_dict();
    bundle.set("type", wire::Value::from_str("BUNDLE"));
    bundle.set("header", b.value.header);
    bundle.set("tag", wire::Value::from_str(b.value.tag));
    bundle.set("remaining", wire::Value::from_int(remaining));
    if (!send_msg(*sock, bundle).ok) return;
    wire::Value payload = wire::Value::from_bytes(std::move(b.value.payload));
    if (!send_msg(*sock, payload).ok) return;
  }
}

// ---------------------------------------------------------------------------
// DealerConnection
// ---------------------------------------------------------------------------
Expected<DealerConnection> DealerConnection::connect(const std::string& host, uint16_t port, int recipient,
                                                    const std::string& setup_id, const std::string& contract_hash,
                                                    const std::vector<uint8_t>& hmac_key, double timeout_s,
                                                    int retries) {
  auto s = TcpSocket::connect(host, port, timeout_s, retries, 0.05);
  if (!s.ok) return forward_fail<DealerConnection>(s);
  DealerConnection c;
  c.sock_ = std::move(s.value);
  c.sock_.set_timeout(timeout_s);
  c.recipient_ = recipient;
  c.setup_id_ = setup_id;
  c.contract_hash_ = contract_hash;
  c.key_ = hmac_key;
  wire::Value hello = wire::Value::make_dict();
  hello.set("type", wire::Value::from_str("HELLO"));
  hello.set("recipient", wire::Value::from_int(recipient));
  hello.set("setup_id", wire::Value::from_str(setup_id));
  hello.set("contract_hash", wire::Value::from_str(contract_hash));
  auto w = c.sock_.send_frame(wire::encode(hello));
  if (!w.ok) return forward_fail<DealerConnection>(w);
  auto chf = c.sock_.recv_frame(1 << 16);
  if (!chf.ok) return forward_fail<DealerConnection>(chf);
  auto ch = wire::decode(chf.value);
  if (!ch.ok) return forward_fail<DealerConnection>(ch);
  if (ch.value.str_or("type", "") == "ERROR") return make_fail<DealerConnection>(ch.value.str_or("code", "DEALER_ERROR"));
  const wire::Value* nonce = ch.value.get("nonce");
  if (ch.value.str_or("type", "") != "CHALLENGE" || !nonce || !nonce->is_bytes())
    return make_fail<DealerConnection>("DEALER_BAD_MESSAGE");
  c.dealer_mode_ = ch.value.str_or("dealer_mode", "");
  c.model_version_ = ch.value.str_or("model_version", "");
  c.profile_id_ = ch.value.str_or("profile_id", "");
  wire::Value auth = wire::Value::make_dict();
  auth.set("type", wire::Value::from_str("AUTH"));
  auth.set("tag", wire::Value::from_str(auth_tag(hmac_key, nonce->bytes)));
  w = c.sock_.send_frame(wire::encode(auth));
  if (!w.ok) return forward_fail<DealerConnection>(w);
  auto okf = c.sock_.recv_frame(1 << 16);
  if (!okf.ok) return forward_fail<DealerConnection>(okf);
  auto ok = wire::decode(okf.value);
  if (!ok.ok) return forward_fail<DealerConnection>(ok);
  if (ok.value.str_or("type", "") == "ERROR") return make_fail<DealerConnection>(ok.value.str_or("code", "DEALER_ERROR"));
  if (ok.value.str_or("type", "") != "AUTH_OK") return make_fail<DealerConnection>("DEALER_BAD_MESSAGE");
  return make_ok(std::move(c));
}

Expected<bool> DealerConnection::verify_bundle(const Bundle& b, int recipient, const std::string& setup_id,
                                               const std::string& contract_hash, const std::vector<uint8_t>& key,
                                               std::set<std::string>& seen_ids) {
  if (!b.header.is_dict()) return make_fail<bool>("DEALER_BAD_MESSAGE");
  // the one bundle verifier of the tree (constant-time tag comparison inside)
  auto tag_ok = highlevel::hmac_verify_with_payload(key, b.header.to_highlevel(), b.payload, b.tag);
  if (!tag_ok.ok || !tag_ok.value) return make_fail<bool>("BUNDLE_BAD_TAG");
  if (b.header.int_or("recipient", -1) != recipient) return make_fail<bool>("BUNDLE_WRONG_RECIPIENT");
  if (b.header.str_or("numeric_contract_hash", "") != contract_hash) return make_fail<bool>("BUNDLE_CONTRACT_MISMATCH");
  if (b.header.str_or("setup_id", "") != setup_id) return make_fail<bool>("BUNDLE_SETUP_MISMATCH");
  if (b.header.int_or("bytes", -1) != static_cast<int64_t>(b.payload.size())) return make_fail<bool>("BUNDLE_SIZE_MISMATCH");
  std::string id = b.header.str_or("material_id", "");
  if (id.empty()) return make_fail<bool>("DEALER_BAD_MESSAGE");
  if (seen_ids.count(id)) return make_fail<bool>("MATERIAL_REUSE");
  seen_ids.insert(id);
  return make_ok(true);
}

Expected<Bundle> DealerConnection::request(const std::string& material_type, const wire::Value& params, int64_t count,
                                           const std::string& gate_id) {
  if (!sock_.valid()) return make_fail<Bundle>("TCP_INVALID_SOCKET");
  wire::Value req = wire::Value::make_dict();
  req.set("type", wire::Value::from_str("REQ"));
  req.set("material_type", wire::Value::from_str(material_type));
  req.set("params", params.is_dict() ? params : wire::Value::make_dict());
  req.set("count", wire::Value::from_int(count));
  req.set("gate_id", wire::Value::from_str(gate_id));
  auto w = sock_.send_frame(wire::encode(req));
  if (!w.ok) return forward_fail<Bundle>(w);
  auto hf = sock_.recv_frame(1 << 24);
  if (!hf.ok) return forward_fail<Bundle>(hf);
  auto h = wire::decode(hf.value);
  if (!h.ok) return forward_fail<Bundle>(h);
  std::string type = h.value.str_or("type", "");
  if (type == "ERROR") return make_fail<Bundle>(h.value.str_or("code", "DEALER_ERROR"));
  if (type != "BUNDLE") return make_fail<Bundle>("DEALER_BAD_MESSAGE");
  Bundle b;
  const wire::Value* header = h.value.get("header");
  if (!header || !header->is_dict()) return make_fail<Bundle>("DEALER_BAD_MESSAGE");
  b.header = *header;
  b.tag = h.value.str_or("tag", "");
  int64_t declared = b.header.int_or("bytes", -1);
  if (declared < 0 || declared > (static_cast<int64_t>(1) << 31)) return make_fail<Bundle>("BUNDLE_SIZE_MISMATCH");
  auto pf = sock_.recv_frame(static_cast<size_t>(declared) + 16);
  if (!pf.ok) return forward_fail<Bundle>(pf);
  auto p = wire::decode(pf.value);
  if (!p.ok) return forward_fail<Bundle>(p);
  if (!p.value.is_bytes()) return make_fail<Bundle>("DEALER_BAD_MESSAGE");
  b.payload = std::move(p.value.bytes);
  auto v = verify_bundle(b, recipient_, setup_id_, contract_hash_, key_, seen_ids_);
  if (!v.ok) return forward_fail<Bundle>(v);
  bytes_received_ += b.payload.size();
  bundles_received_++;
  return make_ok(std::move(b));
}

void DealerConnection::close() {
  if (sock_.valid()) {
    wire::Value bye = wire::Value::make_dict();
    bye.set("type", wire::Value::from_str("BYE"));
    sock_.send_frame(wire::encode(bye));
    sock_.shutdown_both();
    sock_.close();
  }
}

// ---------------------------------------------------------------------------
// keys file
// ---------------------------------------------------------------------------
Expected<std::map<int, std::vector<uint8_t>>> load_keys_file(const std::string& path) {
  using R = std::map<int, std::vector<uint8_t>>;
  std::ifstream in(path, std::ios::binary);
  if (!in) return make_fail<R>("KEYS_IO");
  std::stringstream ss;
  ss << in.rdbuf();
  auto j = json::parse(ss.str());
  if (!j.ok || !j.value.is_object()) return make_fail<R>("KEYS_MALFORMED");
  const json::Value* root = &j.value;
  const json::Value* rec = root->find("recipients");
  if (rec && rec->is_object()) root = rec;
  R out;
  for (const auto& kv : root->obj) {
    if (!kv.second.is_string()) continue;
    if (kv.first != "0" && kv.first != "1") continue;
    auto raw = detail::hex_decode(kv.second.str);
    if (!raw.ok || raw.value.size() < 16) return make_fail<R>("KEYS_MALFORMED");
    out[kv.first == "0" ? 0 : 1] = raw.value;
  }
  if (out.size() != 2) return make_fail<R>("KEYS_MALFORMED");
  if (out[0] == out[1]) return make_fail<R>("KEYS_MALFORMED");
  return make_ok(std::move(out));
}

Expected<bool> write_random_keys_file(const std::string& path) {
  // Same shape as python/opencrab2/platform/dealer_service.py write_keys: {"0": hex, "1": hex}
  json::Value o = json::Value::object();
  o.set("0", json::Value::string(detail::hex_encode(detail::os_random_bytes(32))));
  o.set("1", json::Value::string(detail::hex_encode(detail::os_random_bytes(32))));
  // the recipient keys are secrets: the file is readable by its owner only (mode 0600 on POSIX)
  if (!detail::write_private_file(path, o.dump(false) + "\n")) return make_fail<bool>("KEYS_IO");
  return make_ok(true);
}

